def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    dangerous_bid = 0.0
    rich_competitors = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > budget:
                rich_competitors += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > dangerous_bid:
                    dangerous_bid = float(bid)

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.22))

    tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if tightness < 0:
        tightness = 0.0
    if tightness > 1:
        tightness = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.45
    elif hp <= 6:
        urgency += 0.2

    if no_water_days >= 2:
        urgency += 0.8
    elif no_water_days == 1:
        urgency += 0.3

    urgency += 0.45 * tightness

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if supply <= 17:
        base = 72 + 22 * tightness + 10 * urgency
    elif supply <= 20:
        base = 54 + 18 * tightness + 8 * urgency
    else:
        base = 28 + 14 * tightness + 6 * urgency

    if dangerous_bid > 0:
        if urgency >= 0.9:
            target = dangerous_bid + 2.5
        elif supply <= 17 and hp > 4:
            target = dangerous_bid + 1.2
        elif dangerous_bid >= 150 and hp > 5 and no_water_days == 0:
            target = max(base, avg_prev * 0.45)
        elif dangerous_bid >= 105 and supply >= 22 and hp > 4:
            target = max(base, avg_prev * 0.55)
        else:
            target = max(base, dangerous_bid + 1.0)
    else:
        target = base

    if rich_competitors >= 2 and supply <= 18:
        target += 6.0

    reserve_floor = 0.0
    if hp > 4 and no_water_days == 0:
        reserve_floor = DAILY_SALARY * 1.2
    elif hp > 2:
        reserve_floor = DAILY_SALARY * 0.6

    max_affordable = budget - reserve_floor
    if max_affordable < 0:
        max_affordable = budget * 0.7
    if urgency >= 1.0:
        max_affordable = budget

    bid = min(target, max_affordable)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, dangerous_bid + 2.0 if dangerous_bid > 0 else DAILY_SALARY * 0.9))
    elif hp <= 4 and supply <= 18:
        bid = max(bid, min(budget, dangerous_bid + 1.5 if dangerous_bid > 0 else DAILY_SALARY * 0.78))

    if supply >= 23 and hp >= 7 and no_water_days == 0 and dangerous_bid >= 120:
        bid = min(bid, DAILY_SALARY * 0.42)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no active opponents, bid conservatively to save budget but ensure water.
    if not alive_opponents:
        return max(1, min(my_status['budget'], DAILY_SALARY * 0.4))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid = 0.0

    # My HP is critical, I must get water
    if my_status['hp'] <= 2:
        # Ensure an aggressive bid, at least 90% of salary, or slightly more than highest previous bid.
        bid = max(DAILY_SALARY * 0.9, highest_prev_bid + 5)
    # My HP is healthy, I can afford to be more strategic
    else:
        # If opponents were bidding high yesterday (e.g., >= 80% of salary)
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            # Try to win by bidding slightly higher, but ensure it's at least 50% of salary.
            bid = max(DAILY_SALARY * 0.5, highest_prev_bid + 1)
        # If opponents were bidding moderately or low yesterday
        else:
            # Bid slightly above the highest previous bid, ensuring it's at least 40% of salary.
            bid = max(DAILY_SALARY * 0.4, highest_prev_bid + 1)

    # Ensure the bid does not exceed current budget and is at least 1.
    final_bid = max(1, min(my_status['budget'], bid))
    return final_bid

